events.command:
# Try searching for scipy on quay.io
curl -s "https://quay.io/api/v1/find/repositories?query=scipy&namespace=biocontainers&includeTags=true" 2>/dev/null | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if isinstance(data, dict) and 'results' in data:
        for r in data['results'][:10]:
            name = r.get('name','?')
            tags = list(r.get('tags',{}).keys())[:5] if r.get('tags') else []
            print(f'biocontainers/{name}: {tags}')
    elif isinstance(data, dict):
        print(json.dumps(data, indent=2)[:800])
except Exception as e:
    print(f'Error: {e}')
" 2>&1

