events.command:
# Get tags for biocontainers/scipy
curl -s "https://quay.io/api/v1/repository/biocontainers/scipy/tag/?limit=20" 2>/dev/null | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if 'tags' in data:
        for t in data['tags']:
            print(f\"{t['name']} ({t.get('last_modified','?')})\")
    else:
        print(json.dumps(data, indent=2)[:500])
except Exception as e:
    print(f'Error: {e}')
" 2>&1

